  // ------------------------------------------------------------- flashcards
  const FLASH = [
    { id: 'c02-01', kind: 'numero', q: '40 cámaras por sitio: ¿cuántos frames/s analizas a 15 fps y a 5 fps? ¿Y en 25 sitios?',
      a: '600 vs <b>200 frames/s por sitio</b>; 15,000 vs 5,000 en la flota. Detectar a 5 fps y trackear entre detecciones divide el cómputo por 3; para presencia en una zona alcanza (una persona avanza ≈ 0.3 m entre frames).' },
    { id: 'c02-02', kind: 'numero', q: 'Ancho de banda de un sitio: sub-streams completos vs solo eventos.',
      a: '40 × ≈ 1.5 Mb/s ≈ <b>60 Mb/s continuos</b> (≈ 648 GB/día) contra ≈ 144 eventos/día × ≈ 5.9 MB ≈ 0.85 GB/día ≈ <b>80 kb/s</b> promedio (≈ 760× menos). Un evento = clip de 10 s del principal (≈ 5 MB) + 3 frames (≈ 0.9 MB). Estimaciones: verifica con tus cámaras.' },
    { id: 'c02-03', kind: 'numero', q: '¿Cuánto del NVDEC de una L4 usan 40 sub-streams 1080p a 5 fps?',
      a: 'NVIDIA publica ≈ 903 fps de H.264 1080p por motor NVDEC en Ada (a 2,160 MHz); la L4 tiene 4 → techo ≈ 3,600 fps. 200 fps ≈ <b>6 %</b>; los principales a 15 fps, ≈ 17 %. En un Jetson AGX Orin 64GB (850 MPix/s en H.264) los sub-streams usan ≈ 49 % y los principales no caben.' },
    { id: 'c02-04', kind: 'numero', q: 'Detector ligero con ≈ 400 frames/s medidos por L4 y 200 frames/s por sitio: ¿cuántas GPUs? ¿Y con el detector de M3 (≈ 250)?',
      a: 'Planeada al 70 %: 280 ≥ 200 → <b>1 L4 al ≈ 50 %</b> del máximo (caben ≈ 56 cámaras). Con 250 medidos: 200 ÷ 250 = 80 %, por encima del plan: bajar fps, dos GPUs o un modelo más ligero. El modelo es una decisión de capacidad.' },
    { id: 'c02-05', kind: 'concepto', q: '¿Por qué aquí planeas la GPU al 70 % y en c01 al 50 %?',
      a: 'El tráfico de cámaras es plano y predecible (cámaras × fps, 24/7): no hay picos diurnos ni spikes que absorber. En c01 había pico diario, spikes y failover de una GPU. Queda margen para escenas con más objetos y throttling térmico.' },
    { id: 'c02-06', kind: 'trampa', q: '¿Por qué no puedes balancear frames entre GPUs como si fueran requests?',
      a: 'El tracker guarda estado por stream (dónde estaba cada objeto, cuánto lleva en la zona). Cada cámara se asigna a un pipeline y se queda ahí; si hace falta más GPU, repartes cámaras (20 y 20), no frames.' },
    { id: 'c02-07', kind: 'concepto', q: 'Etapas del pipeline de DeepStream en el edge.',
      a: 'Fuentes RTSP → decode en NVDEC (frames en memoria de GPU) → nvstreammux (batch de 40, uno por cámara) → nvinfer (TensorRT, 640×640) → nvtracker (ids) → nvmsgconv + nvmsgbroker (un JSON por frame a MQTT local) → forwarder (zonas, horarios, dwell). Los frames no vuelven a la CPU; las zonas podrían ir en nvdsanalytics, pero una sola fuente de verdad para los polígonos pesa más.' },
    { id: 'c02-08', kind: 'tradeoff', q: 'DeepStream vs un loop de Python con OpenCV para 40 cámaras.',
      a: 'Python: decode en CPU, frames de ≈ 6.2 MB en RAM (≈ 1.2 GB/s de copias a 200 fps), batch y tracking a mano; bien para un piloto de 5 cámaras. DeepStream: NVDEC, zero-copy, batch y tracker en C++; a cambio, curva de GStreamer y acoplamiento a NVIDIA.' },
    { id: 'c02-09', kind: 'concepto', q: '¿Qué cuesta un batch de 40 streams y qué perilla lo controla?',
      a: 'Latencia: el primer frame espera a los otros 39 (hasta ≈ 200 ms a 5 fps) + ≈ 100 ms de inferencia ≈ 320 ms en el peor caso. <code>batched-push-timeout</code> de nvstreammux empuja batches incompletos: con ≈ 100 ms, batches de ≈ 20 y ≈ 180 ms.' },
    { id: 'c02-10', kind: 'trampa', q: '¿Por qué el recall por frame engaña en video?',
      a: 'Los errores están correlacionados: si pierdes a alguien 1 de cada 5 frames al azar, por evento lo ves casi siempre; si está en una sombra, lo pierdes en todos los frames y por frame casi no se nota. Se evalúa por evento, con replay de clips por el pipeline completo.' },
    { id: 'c02-11', kind: 'numero', q: 'Cascada edge → verificador: ¿cómo se reparte el recall de 95 %?',
      a: 'Se multiplica: 0.98 (edge) × 0.97 (verificador) ≈ 0.95. Por eso el edge va con umbral bajo (no perder nada) y las falsas alarmas se matan en el verificador y en las reglas, no subiendo el umbral del edge.' },
    { id: 'c02-12', kind: 'concepto', q: '¿Cómo mides el recall si las intrusiones no detectadas no dejan rastro?',
      a: 'Walk tests (el equipo de seguridad recorre zonas a horas conocidas, de día y de noche, cada mes) y auditorías de horas aleatorias en el NVR. Las alertas solo te dan precisión.' },
    { id: 'c02-13', kind: 'trampa', q: '¿Por qué “descartada por el SOC” no siempre es un error del modelo?',
      a: '“Persona autorizada” (un guardia) es un acierto del detector y un problema de reglas u horarios; entrenar con eso enseña a no ver personas. Además, los veredictos solo existen para lo que alertó (sesgo de selección): hace falta una muestra aleatoria por cámara.' },
    { id: 'c02-14', kind: 'concepto', q: 'Tres falsas alarmas que no se arreglan reentrenando.',
      a: 'Una telaraña frente al IR (escoba), una zona mal dibujada o un horario que incluye rondas de guardia (config del sitio), un reflejo fijo (máscara de zona). Reentrenar es para sombras, faros, animales y lluvia.' },
    { id: 'c02-15', kind: 'concepto', q: '¿Por qué el forwarder tiene un outbox en disco si DeepStream ya publica mensajes?',
      a: 'El broker de DeepStream no guarda mensajes cuando el destino no está (y en MQTT no reintenta). DeepStream publica a localhost; el forwarder escribe cada evento en disco antes de enviarlo y reintenta con backoff: ningún corte de internet pierde evidencia.' },
    { id: 'c02-16', kind: 'concepto', q: 'Contrato del evento edge → nube: tres propiedades.',
      a: '(1) 202 Accepted: no espera la verificación. (2) Idempotente por un <code>event_id</code> determinista que genera la caja (uuid5): los reintentos responden “duplicate” y no crean otra alerta. (3) Fotos y clip suben directo a S3 con URLs firmadas; el evento lleva solo sus llaves (≈ 1 KB). El sitio sale del token, no del cuerpo.' },
    { id: 'c02-17', kind: 'tradeoff', q: 'Verificador caído: ¿fail-open o fail-closed?',
      a: 'Fail-open total inunda al SOC (≈ 250 candidatos/h contra 50) y la intrusión real se pierde en el ruido; fail-closed total deja la flota ciega en silencio. Fail-open por criticidad: pasado un tope de espera, las zonas críticas llegan “sin verificar” (tope por cámara, etiqueta visible); las demás esperan en la cola.' },
    { id: 'c02-18', kind: 'numero', q: 'El verificador trabaja al ≈ 1 % de una L4. ¿Por qué siempre hay al menos una prendida?',
      a: '≈ 250 candidatos/h × 3 fotos ≈ 0.2 fotos/s. Pero el SLO es de 5 s y un nodo GPU nuevo tarda ≈ 5–13 min (M6): scale-to-zero no cabe. Mínimo 1 (≈ US$588/mes), KEDA sube a 2 con cola sostenida; 2 fijas en dos zonas si el negocio no acepta minutos de “sin verificar”.' },
    { id: 'c02-19', kind: 'trampa', q: '¿Por qué <code>EdgeBoxOffline</code> se evalúa en la nube y no en el sitio?',
      a: 'Una caja muerta no manda alertas, y una serie que dejó de existir no dispara una regla sobre su valor. Se alerta por <b>ausencia</b>: última vez visto &gt; 120 s contra la lista de sitios esperados.' },
    { id: 'c02-20', kind: 'concepto', q: 'Pasos para desplegar un modelo nuevo en 25 sitios.',
      a: 'Gate con replay por sitio y de noche → engine en CI sobre L4 con la misma imagen de DeepStream → bundle chico separado del contenedor, pre-descargado → shadow en 2 sitios → canary de esos 2 una semana → olas de 5, 10 y 8 → symlink a la versión nueva y reinicio (blue/green si el hueco no se acepta) → versión anterior en disco para volver en minutos.' },
    { id: 'c02-21', kind: 'trampa', q: '¿Qué pasa si dejas que cada sitio construya el engine de TensorRT al arrancar?',
      a: 'Minutos de sitio ciego en cada arranque, engines que pueden diferir entre cajas y una calibración INT8 que depende de lo que haya en disco. Se construye una vez en CI sobre una L4 con el mismo TensorRT del contenedor, se valida y se distribuye.' },
    { id: 'c02-22', kind: 'numero', q: 'Costo mensual: híbrido vs todo en la nube, y el punto de equilibrio.',
      a: 'Híbrido ≈ US$9.2k (capex ≈ 6.9k a 36 meses + energía ≈ 0.8k + nube ≈ 1.5k con el techo de 2 verificadores). Todo nube ≈ 13.6k (VPN) a ≈ 21k (KVS) + enlaces. Una L4 por sitio (≈ US$310/mes) se paga desde ≈ 16–30 cámaras. Precios aproximados: verifica.' },
    { id: 'c02-23', kind: 'concepto', q: '¿Cómo detectas una cámara movida o tapada?',
      a: 'Movida: comparar el frame actual con un frame de referencia guardado al dibujar las zonas (similitud de estructura o puntos clave). Tapada o desenfocada: brillo, varianza del Laplaciano y uniformidad contra su línea base de esa hora. Y candidatos por hora fuera de lo normal para esa cámara.' },
    { id: 'c02-24', kind: 'numero', q: 'Presupuesto de latencia de la alerta (p95 ≤ 5 s): ¿qué tramos dominan?',
      a: 'El dwell (1.5 s, fijo por diseño) y la subida de las 3 fotos por URL firmada + el evento (≈ 0.8–1.4 s). Típico ≈ 3.4 s; la suma de los pesimistas (≈ 5.4 s) no es el p95 pero dice dónde está el riesgo. Palancas: subir fotos durante el dwell, URLs en lote, tope a la foto final. El clip (5 MB) no va en el camino crítico.' },
    { id: 'c02-25', kind: 'frase', q: '¿Cómo abres este caso en inglés?',
      a: '“Before I pick any model, let me get the shape of the problem: how many cameras, what counts as an event, how fast an alert has to reach a person, and how many false alarms that person can handle. Video systems are usually limited by bandwidth and decode long before the detector matters.”' },
    { id: 'c02-26', kind: 'frase', q: '¿Cómo dices en inglés por qué detectas en el edge?',
      a: '“The uplink can’t carry the video and a site must keep detecting when the internet drops, so detection runs on one GPU per site and only events leave the site. The cloud improves the alerts, but no site ever depends on it to see.”' },
  ];

